using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.OData;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using Microsoft.OData.Edm;
using Microsoft.OData.ModelBuilder;
using ProjectTimeline.BusinessLogic;
using ProjectTimeline.DataAccessLogic;
using ProjectTimeline.Database;
using ProjectTimeline.UI.WebApi;

var builder = WebApplication.CreateBuilder(args);
var connection = builder.Configuration.GetConnectionString("ProjectTimeline") ?? "Host=localhost;Database=projecttimeline;Username=postgres";
var jwtKey = builder.Configuration["Authentication:SigningKey"] ?? throw new InvalidOperationException("Authentication:SigningKey must be configured for local startup.");
builder.Services.AddDbContext<ProjectTimelineDbContext>(o => o.UseNpgsql(connection, npgsql => npgsql.MigrationsAssembly("ProjectTimeline.Database")));
builder.Services.AddScoped<TimelineService>();
builder.Services.AddScoped<ProjectService>();
builder.Services.AddScoped<RecoveryService>();
builder.Services.AddScoped<ProjectAuthorization>();
builder.Services.AddSingleton<IRecoveryOutbox, FileRecoveryOutbox>();
builder.Services.AddSingleton<ArtifactStorage>();
builder.Services.AddControllers().AddOData(o => o.AddRouteComponents("odata", GetEdmModel()).Select().Filter().OrderBy().Count().SetMaxTop(100));
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o => o.TokenValidationParameters = new TokenValidationParameters { ValidateIssuer = false, ValidateAudience = false, ValidateIssuerSigningKey = true, IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)), RoleClaimType = ClaimTypes.Role, NameClaimType = ClaimTypes.NameIdentifier, ValidateLifetime = true });
builder.Services.AddAuthorization(o => o.AddPolicy("Administrator", p => p.RequireRole("Administrator")));
builder.Services.AddCors(o => o.AddDefaultPolicy(p => p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));
var app = builder.Build();
app.UseCors(); app.UseDefaultFiles(); app.UseStaticFiles(); app.UseRouting(); app.UseAuthentication(); app.UseAuthorization(); app.MapControllers();

using (var scope = app.Services.CreateScope())
{
    try
    {
        var db = scope.ServiceProvider.GetRequiredService<ProjectTimelineDbContext>();
        var password = Environment.GetEnvironmentVariable("PROJECT_TIMELINE_ADMIN_PASSWORD");
        await DatabaseSetup.MigrateAndSeedAsync(db, string.IsNullOrWhiteSpace(password) ? null : PasswordService.Hash(password));
    }
    catch (Exception ex)
    {
        app.Logger.LogError(ex, "Database initialization did not complete. Set PROJECT_TIMELINE_ADMIN_PASSWORD only for first development initialization and verify ConnectionStrings__ProjectTimeline.");
    }
}

app.MapPost("/api/auth/login", async (LoginRequest request, ProjectTimelineDbContext db) =>
{
    var user = await db.Users.Include(x => x.Roles).SingleOrDefaultAsync(x => x.Email == request.Email.Trim().ToLowerInvariant() && x.IsActive);
    if (user is null || !PasswordService.Verify(request.Password, user.PasswordHash)) return Results.Unauthorized();
    var claims = new List<Claim> { new(ClaimTypes.NameIdentifier, user.Id.ToString()), new(ClaimTypes.Email, user.Email) };
    claims.AddRange(user.Roles.Select(r => new Claim(ClaimTypes.Role, r.RoleName)));
    var token = new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken(claims: claims, expires: DateTime.UtcNow.AddHours(8), signingCredentials: new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)), SecurityAlgorithms.HmacSha256)));
    return Results.Ok(new { token, user = ApiMappers.ToDto(user) });
});
app.MapPost("/api/auth/recovery", async (RecoveryRequest request, RecoveryService recovery, CancellationToken ct) => { await recovery.RequestAsync(request.Email, ct); return Results.Ok(new { message = "If the account exists, recovery instructions were delivered through the configured local recovery channel." }); });
app.MapPost("/api/auth/recovery/reset", async (RecoveryResetRequest request, RecoveryService recovery, CancellationToken ct) => await recovery.ResetAsync(request.Token, request.NewPassword, ct) ? Results.Ok(new { message = "Password reset completed." }) : Results.BadRequest(new { error = "The recovery token is invalid, expired, or already used." }));
app.MapGet("/api/me", async (ClaimsPrincipal principal, ProjectTimelineDbContext db) => { var id = UserId(principal); var u = await db.Users.Include(x => x.Roles).SingleOrDefaultAsync(x => x.Id == id); return u is null ? Results.NotFound() : Results.Ok(ApiMappers.ToDto(u)); }).RequireAuthorization();
app.MapPut("/api/me", async (UpdateProfileRequest request, ClaimsPrincipal principal, ProjectTimelineDbContext db) => { if (string.IsNullOrWhiteSpace(request.DisplayName) || request.DisplayName.Trim().Length > 160) return Results.BadRequest(new { error = "Display name is required and must be at most 160 characters." }); var u = await db.Users.FindAsync(UserId(principal)); if (u is null) return Results.NotFound(); u.DisplayName = request.DisplayName.Trim(); if (!string.IsNullOrWhiteSpace(request.Password)) u.PasswordHash = PasswordService.Hash(request.Password); await db.SaveChangesAsync(); return Results.Ok(new { u.Id, u.Email, u.DisplayName }); }).RequireAuthorization();

app.MapGet("/api/admin/users", async (ProjectTimelineDbContext db) => Results.Ok(await db.Users.Include(x => x.Roles).Select(x => ApiMappers.ToDto(x)).ToListAsync())).RequireAuthorization("Administrator");
app.MapPost("/api/admin/users", async (CreateUserRequest r, ProjectTimelineDbContext db) => { if (string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Password) || await db.Users.AnyAsync(x => x.Email == r.Email.ToLower())) return Results.BadRequest(new { error = "Email must be unique and password is required." }); var u = new User { Email = r.Email.Trim().ToLowerInvariant(), DisplayName = r.DisplayName.Trim(), PasswordHash = PasswordService.Hash(r.Password), IsActive = r.IsActive }; db.Users.Add(u); await db.SaveChangesAsync(); foreach (var role in r.Roles ?? []) db.UserRoles.Add(new UserRole { UserId = u.Id, RoleName = role }); await db.SaveChangesAsync(); return Results.Created($"/api/admin/users/{u.Id}", ApiMappers.ToDto(u)); }).RequireAuthorization("Administrator");
app.MapPut("/api/admin/users/{id:guid}", async (Guid id, UpdateUserRequest r, ProjectTimelineDbContext db) => { var u = await db.Users.Include(x => x.Roles).SingleOrDefaultAsync(x => x.Id == id); if (u is null) return Results.NotFound(); u.DisplayName = r.DisplayName.Trim(); u.IsActive = r.IsActive; if (!string.IsNullOrWhiteSpace(r.Password)) u.PasswordHash = PasswordService.Hash(r.Password); db.UserRoles.RemoveRange(u.Roles); foreach (var role in r.Roles ?? []) db.UserRoles.Add(new UserRole { UserId = id, RoleName = role }); await db.SaveChangesAsync(); return Results.Ok(ApiMappers.ToDto(u)); }).RequireAuthorization("Administrator");
app.MapDelete("/api/admin/users/{id:guid}", async (Guid id, ProjectTimelineDbContext db) => { var u = await db.Users.FindAsync(id); if (u is null) return Results.NotFound(); u.IsActive = false; await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization("Administrator");

app.MapGet("/api/projects", async (ClaimsPrincipal principal, ProjectTimelineDbContext db) => { var id = UserId(principal); var q = IsAdmin(principal) ? db.Projects.AsNoTracking() : db.Projects.AsNoTracking().Where(p => p.OwnerId == id || p.Participants.Any(x => x.UserId == id)); return Results.Ok(await q.Select(x => new ProjectDto(x.Id, x.Code, x.Name, x.Description, x.OwnerId, x.CreatedAtUtc, x.UpdatedAtUtc)).ToListAsync()); }).RequireAuthorization();
app.MapPost("/api/projects", async (CreateProjectRequest r, ClaimsPrincipal p, ProjectService service, CancellationToken ct) => { try { var x = await service.CreateAsync(UserId(p), r.Code, r.Name, r.Description, ct); return Results.Created($"/api/projects/{x.Id}", ApiMappers.ToDto(x)); } catch (Exception e) when (e is ArgumentException or DbUpdateException) { return Results.BadRequest(new { error = e.Message }); } }).RequireAuthorization();
app.MapPut("/api/projects/{id:guid}", async (Guid id, UpdateProjectRequest r, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { if (!await authorization.CanManageAsync(id, UserId(p), IsAdmin(p))) return Results.Forbid(); var x = await db.Projects.FindAsync(id); if (x is null) return Results.NotFound(); x.Name = r.Name.Trim(); x.Description = r.Description?.Trim(); await db.SaveChangesAsync(); return Results.Ok(ApiMappers.ToDto(x)); }).RequireAuthorization();
app.MapDelete("/api/projects/{id:guid}", async (Guid id, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { if (!await authorization.CanManageAsync(id, UserId(p), IsAdmin(p))) return Results.Forbid(); var x = await db.Projects.FindAsync(id); if (x is null) return Results.NotFound(); db.Projects.Remove(x); await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization();
app.MapPost("/api/projects/{id:guid}/participants", async (Guid id, AddParticipantRequest r, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { if (!await authorization.CanManageAsync(id, UserId(p), IsAdmin(p))) return Results.Forbid(); var u = await db.Users.SingleOrDefaultAsync(x => x.Email == r.Email.Trim().ToLowerInvariant()); if (u is null || r.ProjectRoleName is not ("Creator" or "Reviewer" or "Contributor")) return Results.BadRequest(new { error = "User or project role is invalid." }); if (await db.ProjectParticipants.AnyAsync(x => x.ProjectId == id && x.UserId == u.Id)) return Results.Conflict(); db.ProjectParticipants.Add(new ProjectParticipant { ProjectId = id, UserId = u.Id, ProjectRoleName = r.ProjectRoleName, IsInvited = false }); await db.SaveChangesAsync(); return Results.Ok(); }).RequireAuthorization();
app.MapGet("/api/projects/{id:guid}/participants", async (Guid id, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { if (!await authorization.CanReadAsync(id, UserId(p), IsAdmin(p))) return Results.Forbid(); return Results.Ok(await db.ProjectParticipants.AsNoTracking().Where(x => x.ProjectId == id).Select(x => new ParticipantDto(x.Id, x.ProjectId, x.UserId, x.User.Email, x.User.DisplayName, x.ProjectRoleName)).ToListAsync()); }).RequireAuthorization();
app.MapPut("/api/projects/{projectId:guid}/participants/{participantId:guid}", async (Guid projectId, Guid participantId, UpdateParticipantRequest r, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { if (!await authorization.CanManageAsync(projectId, UserId(p), IsAdmin(p)) || r.ProjectRoleName is not ("Creator" or "Reviewer" or "Contributor")) return Results.Forbid(); var x = await db.ProjectParticipants.SingleOrDefaultAsync(x => x.Id == participantId && x.ProjectId == projectId); if (x is null) return Results.NotFound(); x.ProjectRoleName = r.ProjectRoleName; await db.SaveChangesAsync(); return Results.Ok(); }).RequireAuthorization();
app.MapDelete("/api/projects/{projectId:guid}/participants/{participantId:guid}", async (Guid projectId, Guid participantId, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { if (!await authorization.CanManageAsync(projectId, UserId(p), IsAdmin(p))) return Results.Forbid(); var x = await db.ProjectParticipants.SingleOrDefaultAsync(x => x.Id == participantId && x.ProjectId == projectId); if (x is null) return Results.NotFound(); db.ProjectParticipants.Remove(x); await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization();

app.MapGet("/api/projects/{id:guid}/timelines", async (Guid id, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { if (!await authorization.CanReadAsync(id, UserId(p), IsAdmin(p))) return Results.Forbid(); return Results.Ok(await db.Timelines.AsNoTracking().Where(x => x.ProjectId == id).Select(x => new TimelineDto(x.Id, x.ProjectId, x.Code, x.Name, x.CreatedAtUtc, x.UpdatedAtUtc)).ToListAsync()); }).RequireAuthorization();
app.MapPost("/api/projects/{id:guid}/timelines", async (Guid id, CreateTimelineRequest r, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { if (!await authorization.CanWriteAsync(id, UserId(p), IsAdmin(p))) return Results.Forbid(); var x = new Timeline { ProjectId = id, Code = r.Code.Trim().ToUpperInvariant(), Name = r.Name.Trim() }; if (x.Code.Length is < 1 or > 32 || x.Name.Length is < 1 or > 160) return Results.BadRequest(); db.Timelines.Add(x); await db.SaveChangesAsync(); return Results.Created($"/api/timelines/{x.Id}", ApiMappers.ToDto(x)); }).RequireAuthorization();
app.MapPut("/api/timelines/{id:guid}", async (Guid id, UpdateTimelineRequest r, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { var x = await db.Timelines.FindAsync(id); if (x is null) return Results.NotFound(); if (!await authorization.CanWriteAsync(x.ProjectId, UserId(p), IsAdmin(p))) return Results.Forbid(); x.Name = r.Name.Trim(); await db.SaveChangesAsync(); return Results.Ok(ApiMappers.ToDto(x)); }).RequireAuthorization();
app.MapDelete("/api/timelines/{id:guid}", async (Guid id, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { var x = await db.Timelines.FindAsync(id); if (x is null) return Results.NotFound(); if (!await authorization.CanWriteAsync(x.ProjectId, UserId(p), IsAdmin(p))) return Results.Forbid(); db.Timelines.Remove(x); await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization();
app.MapGet("/api/timelines/{id:guid}/entries", async (Guid id, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { var project = await db.Timelines.Where(x => x.Id == id).Select(x => x.ProjectId).SingleOrDefaultAsync(); if (project == Guid.Empty || !await authorization.CanReadAsync(project, UserId(p), IsAdmin(p))) return Results.Forbid(); return Results.Ok(await db.TimelineEntries.AsNoTracking().Where(x => x.TimelineId == id).OrderBy(x => x.EntryNumber).Select(x => new EntryDto(x.Id, x.TimelineId, x.EntryNumber, x.Title, x.Content, x.Status, x.AuthorId, x.CreatedAtUtc, x.UpdatedAtUtc)).ToListAsync()); }).RequireAuthorization();
app.MapPost("/api/timelines/{id:guid}/entries", async (Guid id, CreateEntryRequest r, ClaimsPrincipal p, TimelineService service, ProjectTimelineDbContext db, ProjectAuthorization authorization, CancellationToken ct) => { var project = await db.Timelines.Where(x => x.Id == id).Select(x => x.ProjectId).SingleOrDefaultAsync(ct); if (project == Guid.Empty || !await authorization.CanWriteAsync(project, UserId(p), IsAdmin(p), ct)) return Results.Forbid(); try { var x = await service.AddEntryAsync(id, UserId(p), r.Title, r.Content, ct); return Results.Created($"/api/entries/{x.Id}", ApiMappers.ToDto(x)); } catch (Exception e) when (e is ArgumentException or KeyNotFoundException) { return Results.BadRequest(new { error = e.Message }); } }).RequireAuthorization();
app.MapPut("/api/entries/{id:guid}", async (Guid id, UpdateEntryRequest r, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { var x = await db.TimelineEntries.Include(e => e.Timeline).SingleOrDefaultAsync(e => e.Id == id); if (x is null) return Results.NotFound(); if (!await authorization.CanWriteAsync(x.Timeline.ProjectId, UserId(p), IsAdmin(p))) return Results.Forbid(); x.Title = r.Title.Trim(); x.Content = r.Content.Trim(); x.Status = r.Status.Trim(); await db.SaveChangesAsync(); return Results.Ok(ApiMappers.ToDto(x)); }).RequireAuthorization();
app.MapDelete("/api/entries/{id:guid}", async (Guid id, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { var x = await db.TimelineEntries.Include(e => e.Timeline).SingleOrDefaultAsync(e => e.Id == id); if (x is null) return Results.NotFound(); if (!await authorization.CanWriteAsync(x.Timeline.ProjectId, UserId(p), IsAdmin(p))) return Results.Forbid(); db.TimelineEntries.Remove(x); await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization();
app.MapPost("/api/entries/{id:guid}/artifacts", async (Guid id, IFormFile file, ClaimsPrincipal p, ProjectTimelineDbContext db, ArtifactStorage storage, ProjectAuthorization authorization, CancellationToken ct) => { var e = await db.TimelineEntries.Include(x => x.Timeline).ThenInclude(x => x.Project).SingleOrDefaultAsync(x => x.Id == id, ct); if (e is null) return Results.NotFound(); if (!await authorization.CanWriteAsync(e.Timeline.ProjectId, UserId(p), IsAdmin(p), ct)) return Results.Forbid(); try { await storage.SaveAsync(e.Timeline.Project.Code, e.Timeline.Code, e.EntryNumber, file.FileName, file.OpenReadStream(), ct); var a = new TimelineArtifact { EntryId = id, FileName = Path.GetFileName(file.FileName), RelativePath = $"{e.Timeline.Project.Code}/{e.Timeline.Code}/{e.EntryNumber}/{Path.GetFileName(file.FileName)}", ContentType = file.ContentType, Length = file.Length }; db.TimelineArtifacts.Add(a); await db.SaveChangesAsync(ct); return Results.Ok(ApiMappers.ToDto(a)); } catch (ArgumentException ex) { return Results.BadRequest(new { error = ex.Message }); } }).RequireAuthorization();
app.MapGet("/api/entries/{id:guid}/artifacts", async (Guid id, ClaimsPrincipal p, ProjectTimelineDbContext db, ProjectAuthorization authorization) => { var entry = await db.TimelineEntries.AsNoTracking().Include(x => x.Timeline).SingleOrDefaultAsync(x => x.Id == id); if (entry is null) return Results.NotFound(); if (!await authorization.CanReadAsync(entry.Timeline.ProjectId, UserId(p), IsAdmin(p))) return Results.Forbid(); return Results.Ok(await db.TimelineArtifacts.AsNoTracking().Where(x => x.EntryId == id).Select(x => new ArtifactDto(x.Id, x.EntryId, x.FileName, x.ContentType, x.Length, x.CreatedAtUtc)).ToListAsync()); }).RequireAuthorization();
app.MapGet("/api/artifacts/{id:guid}", async (Guid id, ClaimsPrincipal p, ProjectTimelineDbContext db, ArtifactStorage storage, ProjectAuthorization authorization, CancellationToken ct) => { var a = await db.TimelineArtifacts.Include(x => x.Entry).ThenInclude(x => x.Timeline).ThenInclude(x => x.Project).SingleOrDefaultAsync(x => x.Id == id, ct); if (a is null) return Results.NotFound(); if (!await authorization.CanReadAsync(a.Entry.Timeline.ProjectId, UserId(p), IsAdmin(p), ct)) return Results.Forbid(); try { var path = storage.GetSafePath(a.Entry.Timeline.Project.Code, a.Entry.Timeline.Code, a.Entry.EntryNumber, a.FileName); return !File.Exists(path) ? Results.NotFound() : Results.File(path, a.ContentType, a.FileName); } catch (ArgumentException) { return Results.BadRequest(); } }).RequireAuthorization();
app.MapDelete("/api/artifacts/{id:guid}", async (Guid id, ClaimsPrincipal p, ProjectTimelineDbContext db, ArtifactStorage storage, ProjectAuthorization authorization) => { var a = await db.TimelineArtifacts.Include(x => x.Entry).ThenInclude(x => x.Timeline).SingleOrDefaultAsync(x => x.Id == id); if (a is null) return Results.NotFound(); if (!await authorization.CanWriteAsync(a.Entry.Timeline.ProjectId, UserId(p), IsAdmin(p))) return Results.Forbid(); var path = storage.GetSafePath(a.Entry.Timeline.Project.Code, a.Entry.Timeline.Code, a.Entry.EntryNumber, a.FileName); if (File.Exists(path)) File.Delete(path); db.TimelineArtifacts.Remove(a); await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization();
app.MapFallbackToFile("index.html");
app.Run();

static IEdmModel GetEdmModel() { var b = new ODataConventionModelBuilder(); b.EntitySet<ProjectDto>("Projects"); return b.GetEdmModel(); }
static Guid UserId(ClaimsPrincipal p) => Guid.Parse(p.FindFirstValue(ClaimTypes.NameIdentifier)!);
static bool IsAdmin(ClaimsPrincipal p) => p.IsInRole("Administrator");
public partial class Program { }
